app.use((req, res, next) => {
    const allowedOrigins = ['http://localhost:3000', 'http://localhost:5173'];
    const origin = req.headers.origin;
    if (allowedOrigins.includes(origin)) {
        res.header('Access-Control-Allow-Origin', origin);
        res.header('Access-Control-Allow-Methods', 'GET, POST, PUT, DELETE, OPTIONS');
        res.header('Access-Control-Allow-Headers', 'Content-Type, Authorization, x-arturo-key, x-request-id');
    }
    if (req.method === 'OPTIONS') return res.sendStatus(allowedOrigins.includes(origin) ? 200 : 403);
    next();
});

app.use((req, res, next) => {
    if (ipBlocker.isBlocked(req)) {
        return res.status(403).json({
            error: 'Acceso denegado',
            mensaje: 'Tu IP ha sido bloqueada temporalmente por actividad sospechosa.'
        });
    }
    next();
});

isBlocked(req) {
    const ip = req.ip || req.socket?.remoteAddress || '127.0.0.1';
    if (ip === '127.0.0.1' || ip === '::1' || ip === '::ffff:127.0.0.1' || ip.startsWith('10.') || ip.startsWith('172.') || ip.startsWith('192.168.')) return false;
    if (this.blockedIps.has(ip)) return true;
    if (this.accessesSensitivePath(req, ip)) return true;
    if (this.exceedsLimit(ip)) { this.blockIps(ip); return true; }
    return false;
}

